```cpp
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> nums = {1, 3, 3, 2, 5, 3};
    int maxVal = 5;

    vector<int> freq(maxVal + 1, 0);

    for (int i = 0; i < nums.size(); i++) {
        int value = nums[i];
        if (value >= 0 && value <= maxVal) {
            freq[value]++;
        }
    }

    for (int i = 0; i <= maxVal; i++) {
        cout << i << " : " << freq[i] << "\n";
    }

    return 0;
}
